CREATE OR REPLACE FUNCTION public.rpc_get_notification_preferences(p_expected_user_id uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); d public.notification_preferences%rowtype; v_exists boolean:=true;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_expected_user_id is null or p_expected_user_id<>v_uid then
    raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
  if p_role is null or p_role not in ('REQUESTER','WORKER') then
    raise exception 'INVALID_NOTIFICATION_ROLE' using errcode='22023'; end if;
  select * into d from public.notification_preferences where user_id=v_uid and role_context=p_role;
  if not found then
    v_exists:=false;
    -- An absent row is revision0, with the existing emitter defaults. Reading
    -- never inserts a row and never acquires transport permission.
    d:=jsonb_populate_record(null::public.notification_preferences,
      '{"revision":0,"in_app_enabled":true,"push_enabled":false,"opportunities_enabled":true,
        "responses_enabled":true,"dogovor_enabled":true,"execution_enabled":true,
        "recovery_enabled":true,"account_enabled":true,"quiet_hours_enabled":false,
        "quiet_start":null,"quiet_end":null,"quiet_timezone":"Europe/Belgrade",
        "urgent_overrides_quiet_hours":false}'::jsonb);
    d.role_context:=p_role;
  end if;
  return jsonb_build_object('userId',v_uid,'exists',v_exists,'roleContext',d.role_context,'revision',d.revision,
    'updatedAt',d.updated_at,'settings',private.notification_preferences_settings(d));
end
$function$

CREATE OR REPLACE FUNCTION public.rpc_get_public_profile(p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_profile public.app_profiles;
  v_completed bigint := 0;
  v_reputation jsonb;
begin
  if v_actor is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if p_profile_id is null then
    raise exception 'PROFILE_ID_REQUIRED' using errcode = '22023';
  end if;

  select p.*
  into v_profile
  from public.app_profiles p
  where p.id = p_profile_id
    and p.profile_status = 'ACTIVE'
    and p.kind in ('REQUESTER', 'WORKER');

  if not found then
    return null;
  end if;

  if private.closure_account_restricted(v_actor) or private.closure_account_restricted(v_profile.account_id) then return null; end if;
  if private.safety_pair_blocked(v_actor,v_profile.account_id) then return null; end if;
  if not private.accounts_same_world(v_actor, v_profile.account_id) then return null; end if;
  if v_profile.kind = 'REQUESTER' then
    select count(*)
    into v_completed
    from public.agreements a
    where a.requester_profile_id = v_profile.id
      and a.status = 'COMPLETED';
  else
    select count(*)
    into v_completed
    from public.agreements a
    where a.worker_profile_id = v_profile.id
      and a.status = 'COMPLETED';
  end if;

  v_reputation:=private.account_reputation(v_profile.account_id);
  return jsonb_build_object(
    'profileId', v_profile.id,
    'role', v_profile.kind,
    'displayName', nullif(btrim(v_profile.display_name), ''),
    'avatarPath', v_profile.avatar_path,
    'city', nullif(btrim(v_profile.city), ''),
    'publicSummary', jsonb_build_object(
      'headline', case when v_profile.kind = 'WORKER' then nullif(btrim(v_profile.headline), '') else null end,
      'bio', case when v_profile.kind = 'WORKER' then nullif(btrim(v_profile.bio), '') else null end
    ),
    'trust', jsonb_build_object(
      'ratingAverage', v_reputation->'averageRating',
      'reviewCount', v_reputation->'reviewCount',
      'completedCount', v_completed,
      'identityVerified', false,
      'ratingAvailable', (v_reputation->>'reviewCount')::bigint>0,
      'reviewsAvailable', true,
      'identityVerificationAvailable', false
    )
  );
end;
$function$
